def safe_divide(a, b):
    if b == 0:
        return None
    return a / b

def unique_in_order(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def is_valid_brackets(text):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for char in text:
        if char in '([{':
            stack.append(char)
        elif not stack or stack.pop() != pairs[char]:
            return False
    return not stack

def merge_intervals(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda item: item[0])
    merged = [intervals[0][:]]
    for start, end in intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

class TTLCache:
    def __init__(self):
        self._data = {}

    def set(self, key, value, ttl, now):
        self._data[key] = (value, now + ttl)

    def get(self, key, now):
        item = self._data.get(key)
        if item is None:
            return None
        value, expires_at = item
        if now >= expires_at:
            del self._data[key]
            return None
        return value
